<h1>Audit Log</h1>
<p class="muted">Security and data-change events for your account.</p>
<form method="get" class="card"><div class="grid"><p><label>Event</label><select name="event"><option value="">All events</option><?php foreach($events as $event):?><option value="<?=e($event)?>" <?=($filterEvent===$event?'selected':'')?>><?=e($event)?></option><?php endforeach;?></select></p><p><label>Rows</label><select name="limit"><?php foreach([50,100,200] as $n):?><option value="<?=$n?>" <?=($limit===$n?'selected':'')?>><?=$n?></option><?php endforeach;?></select></p></div><button>Filter</button> <a href="/audit-log">Reset</a></form>
<div class="card table-wrap"><table><thead><tr><th>Date</th><th>Event</th><th>Entity</th><th>ID</th><th>Message</th><th>IP</th></tr></thead><tbody><?php foreach($logs as $log):?><tr><td><?=e($log['created_at'])?></td><td><?=e($log['event_type'])?></td><td><?=e($log['entity_type']??'—')?></td><td><?=e($log['entity_id']??'—')?></td><td><?=e($log['message']??'—')?></td><td><?=e($log['ip_address']??'—')?></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="6" class="muted">No audit events found.</td></tr><?php endif;?></tbody></table></div>
